PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE places (
    id TEXT PRIMARY KEY,
    name TEXT,
    name_en TEXT,
    slug TEXT UNIQUE,
    category_id TEXT,
    subcategory_id TEXT,
    custom_category TEXT,

    address TEXT,
    area TEXT,
    phone TEXT,
    whatsapp TEXT,
    maps_link TEXT,

    latitude REAL,
    longitude REAL,

    description TEXT,

    logo_url TEXT,
    cover_image_url TEXT,

    owner_id TEXT,
    owner_email TEXT,

    status TEXT,
    is_verified INTEGER DEFAULT 0,
    verification_status TEXT,

    offer_count INTEGER DEFAULT 0,
    product_count INTEGER DEFAULT 0,

    services_json TEXT,
    social_json TEXT,
    stats_json TEXT,
    working_hours_json TEXT,

    created_at INTEGER,
    updated_at INTEGER
, is_sponsored INTEGER DEFAULT 0, is_featured INTEGER DEFAULT 0, sponsored_until INTEGER DEFAULT NULL, priority INTEGER DEFAULT 0, locality_id INTEGER REFERENCES localities(id) ON DELETE SET NULL, trust_score INTEGER DEFAULT 0);
CREATE TABLE reviews (
    id TEXT PRIMARY KEY,
    place_id TEXT NOT NULL,

    user_id TEXT,
    user_name TEXT,
    user_photo TEXT,

    place_name TEXT,
    place_slug TEXT,

    rating INTEGER,
    comment TEXT,

    is_admin_generated INTEGER DEFAULT 0,
    edit_count INTEGER DEFAULT 0,

    created_at INTEGER,
    updated_at INTEGER
, is_reported INTEGER DEFAULT 0, report_count INTEGER DEFAULT 0, last_report_reason TEXT, reported_at INTEGER, last_reporter_name TEXT, is_reviewed_by_admin INTEGER DEFAULT 0, admin_review_status TEXT, admin_review_note TEXT, reviewed_at INTEGER);
CREATE TABLE categories (
    id TEXT PRIMARY KEY,
    name TEXT,
    name_en TEXT,
    slug TEXT,
    icon TEXT,
    image_url TEXT,
    description TEXT,
    parent_id TEXT,
    sort_order INTEGER DEFAULT 0,
    is_active INTEGER DEFAULT 1,
    created_at INTEGER,
    updated_at INTEGER
);
CREATE TABLE users (
    id TEXT PRIMARY KEY,
    name TEXT,
    email TEXT,
    photo_url TEXT,
    phone TEXT,
    role TEXT,
    status TEXT,
    created_at INTEGER,
    updated_at INTEGER
);
CREATE TABLE category_requests (id TEXT PRIMARY KEY, category_name TEXT, place_name TEXT, owner_name TEXT, user_id TEXT, status TEXT DEFAULT 'pending', created_at INTEGER, reviewed_at INTEGER);
CREATE TABLE verification_requests (id TEXT PRIMARY KEY, place_id TEXT, place_name TEXT, owner_id TEXT, owner_name TEXT, owner_email TEXT, phone TEXT, notes TEXT, status TEXT DEFAULT 'pending', verified_until INTEGER, created_at INTEGER, reviewed_at INTEGER);
CREATE TABLE fcm_tokens (token TEXT PRIMARY KEY, user_id TEXT, user_name TEXT, platform TEXT, user_agent TEXT, created_at INTEGER, updated_at INTEGER);
CREATE TABLE ads (id TEXT PRIMARY KEY, title TEXT, place_id TEXT, link TEXT, image_url TEXT, placement TEXT DEFAULT 'all', priority INTEGER DEFAULT 10, is_active INTEGER DEFAULT 1, start_date INTEGER, end_date INTEGER, clicks INTEGER DEFAULT 0, created_at INTEGER, created_by TEXT);
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE place_reports (
  id TEXT PRIMARY KEY,
  place_id TEXT NOT NULL,
  reason TEXT NOT NULL,
  details TEXT,
  reporter_name TEXT,
  status TEXT DEFAULT 'new',
  created_at INTEGER NOT NULL,
  reviewed_at INTEGER,
  reviewed_by TEXT,
  FOREIGN KEY (place_id) REFERENCES places(id) ON DELETE CASCADE
);
CREATE TABLE countries (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name_ar TEXT NOT NULL,
  name_en TEXT NOT NULL,
  iso_code TEXT NOT NULL UNIQUE,
  slug TEXT NOT NULL UNIQUE,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE governorates (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  country_id INTEGER NOT NULL REFERENCES countries(id) ON DELETE CASCADE,
  name_ar TEXT NOT NULL,
  name_en TEXT NOT NULL,
  official_code TEXT,
  slug TEXT NOT NULL UNIQUE,
  latitude REAL,
  longitude REAL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE centers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  governorate_id INTEGER NOT NULL REFERENCES governorates(id) ON DELETE CASCADE,
  name_ar TEXT NOT NULL,
  name_en TEXT NOT NULL,
  official_code TEXT,
  slug TEXT NOT NULL UNIQUE,
  latitude REAL,
  longitude REAL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE localities (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  center_id INTEGER NOT NULL REFERENCES centers(id) ON DELETE CASCADE,
  parent_locality_id INTEGER REFERENCES localities(id) ON DELETE SET NULL,
  name_ar TEXT NOT NULL,
  name_en TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('city','village','local_unit')),
  official_code TEXT,
  slug TEXT NOT NULL UNIQUE,
  latitude REAL,
  longitude REAL,
  population INTEGER,
  is_verified INTEGER NOT NULL DEFAULT 0,
  source_reference TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_places_category
ON places(category_id);
CREATE INDEX idx_places_area
ON places(area);
CREATE INDEX idx_places_status
ON places(status);
CREATE INDEX idx_places_owner
ON places(owner_id);
CREATE INDEX idx_places_name
ON places(name);
CREATE INDEX idx_places_slug
ON places(slug);
CREATE INDEX idx_reviews_place_id
ON reviews(place_id);
CREATE INDEX idx_reviews_user_id
ON reviews(user_id);
CREATE INDEX idx_reviews_created_at
ON reviews(created_at);
CREATE INDEX idx_reviews_rating
ON reviews(rating);
CREATE INDEX idx_categories_slug
ON categories(slug);
CREATE INDEX idx_categories_parent
ON categories(parent_id);
CREATE INDEX idx_categories_active
ON categories(is_active);
CREATE INDEX idx_users_email
ON users(email);
CREATE INDEX idx_users_role
ON users(role);
CREATE INDEX idx_places_category_id ON places(category_id);
CREATE INDEX idx_place_reports_status_created
  ON place_reports(status, created_at DESC);
CREATE INDEX idx_place_reports_place
  ON place_reports(place_id, created_at DESC);
CREATE INDEX idx_places_verified_updated
  ON places(is_verified, updated_at DESC);
CREATE INDEX idx_places_sponsored_priority
  ON places(is_sponsored, is_featured, priority DESC, updated_at DESC);
CREATE INDEX idx_reviews_reported
  ON reviews(is_reported, created_at DESC);
CREATE INDEX idx_localities_center ON localities(center_id);
CREATE INDEX idx_localities_parent ON localities(parent_locality_id);
CREATE INDEX idx_localities_type ON localities(type);
CREATE INDEX idx_places_locality ON places(locality_id);
